// ---------------------------------------------------------------
// Deterministic BMS alert evaluation.
//
// Every rule below is explicit. Thresholds come from measurements on
// this specific bank, not from generic guidance:
//   current deadband      2.07 A   (verified: nothing between 0 and 2.07)
//   resting cell spread   14-21 mV
//   loaded cell spread    35-50 mV
//   internal resistance   0.2-0.4 mOhm per pack
//   pack rating           200 A continuous, 4 packs = 800 A bank
// ---------------------------------------------------------------

const CRIT_REPEAT_H = 12;   // re-notify an unresolved critical this often
const WARN_REPEAT_H = 24;
const MISSING_PACK_GRACE_MIN = 30;  // BLE drops are routine; wait before alarming

const s = msg.payload;
const now = Date.now();
const alerts = [];

function add(sev, id, title, detail) {
    alerts.push({ sev, id, title, detail });
}

// --- collector reachable at all? -------------------------------------
// This is the failure this whole flow exists to catch: monitoring that
// has quietly stopped. A non-object payload or an HTTP error means the
// service is down, the Cerbo is unreachable, or the port moved.
if (msg.statusCode && msg.statusCode !== 200) {
    add('CRITICAL', 'collector_http',
        'BMS collector returned HTTP ' + msg.statusCode,
        'No battery telemetry is being collected. Check: svstat /service/bms-collector');
} else if (!s || typeof s !== 'object') {
    add('CRITICAL', 'collector_unreachable',
        'BMS collector unreachable',
        'No response from http://127.0.0.1:8088. The service may have stopped.');
} else if (s.status === 'no_data') {
    add('CRITICAL', 'collector_no_data',
        'BMS collector is running but has no recent samples',
        s.note || 'The poller may be stopped or Bluetooth may have failed.');
} else {

    // --- packs missing ------------------------------------------------
    // Tracked with a first-seen timestamp so a single missed BLE poll
    // does not page you. Only sustained absence counts.
    const seenSince = flow.get('missingSince') || {};
    if (s.packs_reporting < s.packs_expected) {
        if (!seenSince.missing) seenSince.missing = now;
        const mins = Math.round((now - seenSince.missing) / 60000);
        if (mins >= MISSING_PACK_GRACE_MIN) {
            add('CRITICAL', 'packs_missing',
                `Only ${s.packs_reporting} of ${s.packs_expected} packs reporting (${mins} min)`,
                'A pack has stopped answering over Bluetooth. You are blind to it; '
                + 'it has not necessarily failed. Check the dashboard timeline.');
        }
    } else {
        delete seenSince.missing;
    }
    flow.set('missingSince', seenSince);

    // --- discharge disabled: pack isolated from the bank ---------------
    // Sets no protection or failure bit and the cells look healthy, so
    // nothing else would surface it.
    (s.packs_with_discharge_disabled || []).forEach(p => {
        add('CRITICAL', 'discharge_off_' + p,
            `${p}: discharge disabled`,
            'This pack is electrically isolated and carries none of the load. '
            + 'The remaining packs take its share. Re-enable via the LiTime app '
            + '(stop the collector first), or power-cycle the pack.');
    });

    // --- charge FET open while charge is actually available -------------
    // The flag on its own is normal: every healthy pack opens its charge
    // FET on reaching full, and at a dock a full pack may sit that way for
    // a long time. What is not normal is refusing charge while the other
    // packs are taking real current - that pack is not participating.
    const charging = Object.keys(s.packs || {}).filter(k => {
        const c = (s.packs[k] || {}).current_a || {};
        return c.max != null && c.max > 10;
    });
    if (charging.length >= 2) {
        (s.packs_not_accepting_charge || []).forEach(p => {
            const c = (s.packs[p] || {}).current_a || {};
            if (c.max != null && c.max <= 2)
                add('WARNING', 'charge_refused_' + p,
                    `${p}: not accepting charge while the bank is charging`,
                    `${charging.length} packs are taking current and this one is not. `
                    + 'Normal only if it is genuinely full first; if it persists across '
                    + 'a discharge and recharge, the pack may be stuck believing it is '
                    + 'full. A full power-off via the LiTime app clears that state.');
        });
    }

    // --- charge blocked continuously for days ---------------------------
    // Slower signal for the case above when the bank never charges hard
    // enough to trigger it. Tracked here because the summary window is
    // only an hour.
    const blockedSince = flow.get('chargeBlockedSince') || {};
    Object.keys(s.packs || {}).forEach(k => {
        if ((s.packs[k] || {}).charge_blocked_now) {
            if (!blockedSince[k]) blockedSince[k] = now;
            const hrs = Math.round((now - blockedSince[k]) / 3600000);
            if (hrs >= 48)
                add('WARNING', 'charge_blocked_long_' + k,
                    `${k}: charge FET open continuously for ${hrs} h`,
                    'A pack that never re-accepts charge across multiple days is '
                    + 'likely stuck believing it is full, and is doing less work than '
                    + 'its siblings. Compare cycle counts on the dashboard.');
        } else {
            delete blockedSince[k];
        }
    });
    flow.set('chargeBlockedSince', blockedSince);

    // --- BMS protection / failure bits --------------------------------
    if (s.any_alarm_flag_set) {
        Object.keys(s.packs || {}).forEach(k => {
            const a = (s.packs[k] || {}).alarms || {};
            const bits = []
                .concat(a.protections_seen || [])
                .concat(a.protection_raw_nonzero || [])
                .concat(a.failure_field_nonzero || []);
            if (bits.length) {
                add('CRITICAL', 'alarm_' + k,
                    `${k}: BMS alarm flag set`,
                    'Flags: ' + bits.join(', ') + '. Note the bit definitions are '
                    + 'inherited and unvalidated - treat any non-zero value as '
                    + '"something tripped" and inspect directly.');
            }
        });
    }

    // --- cell voltage limits ------------------------------------------
    Object.keys(s.packs || {}).forEach(k => {
        const p = s.packs[k] || {};
        const cv = p.cell_v || {};
        if (cv.max != null && cv.max > 3.65)
            add('CRITICAL', 'cell_high_' + k,
                `${k}: cell at ${cv.max.toFixed(3)} V`,
                'Above the 3.65 V practical ceiling for LiFePO4. Overvoltage '
                + 'protection trips near 3.75 V. Reduce charge voltage.');
        if (cv.min != null && cv.min < 2.50)
            add('CRITICAL', 'cell_low_' + k,
                `${k}: cell at ${cv.min.toFixed(3)} V`,
                'Below the 2.50 V floor. Capacity is being removed permanently. '
                + 'Stop discharging and recharge.');

        // --- temperature -----------------------------------------------
        const t = p.temp_c || {};
        if (t.cell_max != null && t.cell_max > 55)
            add('CRITICAL', 'temp_high_' + k,
                `${k}: cell temperature ${t.cell_max} C`,
                'Above 55 C the BMS should be limiting current. Investigate '
                + 'ventilation and load.');
        else if (t.cell_max != null && t.cell_max > 45)
            add('WARNING', 'temp_warm_' + k,
                `${k}: cell temperature ${t.cell_max} C`,
                'Above 45 C ageing accelerates markedly.');

        // Charging below freezing causes lithium plating - permanent and a
        // genuine safety issue. The BMS should block it; this verifies it did.
        const cur = p.current_a || {};
        if (t.cell_min != null && t.cell_min < 0 && cur.max != null && cur.max > 2)
            add('CRITICAL', 'cold_charge_' + k,
                `${k}: charging at ${t.cell_min} C`,
                'Charging below 0 C causes lithium plating - permanent damage. '
                + 'Stop charging until the pack warms.');
    });

    // --- pack-to-pack temperature spread -------------------------------
    const temps = Object.keys(s.packs || {})
        .map(k => ((s.packs[k] || {}).temp_c || {}).cell_max)
        .filter(v => v != null);
    if (temps.length >= 2 && (Math.max(...temps) - Math.min(...temps)) > 5)
        add('WARNING', 'temp_spread',
            `Pack temperatures differ by ${Math.max(...temps) - Math.min(...temps)} C`,
            'Identical packs sharing a compartment should track within a couple '
            + 'of degrees. A consistently hotter pack is carrying more current, '
            + 'has higher internal resistance, or has restricted airflow.');

    // --- current sharing under real load -------------------------------
    // Only meaningful above the deadband, which the collector already
    // enforces by only including samples over 10 A.
    Object.keys(s.current_sharing || {}).forEach(phase => {
        const sh = s.current_sharing[phase] || {};
        if (sh.spread_pct != null && sh.spread_pct > 15)
            add('WARNING', 'sharing_' + phase,
                `Current sharing ${sh.spread_pct}% apart on ${phase}`,
                'Healthy is within about 3%. Sustained deviation suggests a cable, '
                + 'terminal or fuse with elevated resistance on the odd pack.');
    });

    // --- cell spread, judged against the bank's condition ---------------
    Object.keys(s.packs || {}).forEach(k => {
        const p = s.packs[k] || {};
        const d = p.cell_delta_mv || {};
        const cv = p.cell_v || {};
        const cur = p.current_a || {};
        if (d.max == null) return;
        // LiFePO4 is flat between 3.20 and 3.40 V, so the same imbalance
        // shows as a much smaller number there than at the top of charge.
        const loaded = (cur.max != null && Math.abs(cur.max) > 20) ||
                       (cur.min != null && Math.abs(cur.min) > 20);
        const limit = loaded ? 120 : (cv.max != null && cv.max >= 3.45 ? 100 : 60);
        if (d.max > limit)
            add('WARNING', 'spread_' + k,
                `${k}: cell spread ${d.max} mV`,
                `Above the ${limit} mV limit for the current condition. A single `
                + 'excursion means little; a pack trending upward at the same '
                + 'operating point over weeks indicates a cell losing capacity.');
    });
}

// ---------------------------------------------------------------
// Deduplication. Notify on first appearance, then repeat only after
// the interval for that severity. Send one all-clear when a condition
// that was notified goes away.
// ---------------------------------------------------------------
const state = flow.get('alertState') || {};
const active = {};
const toSend = [];

alerts.forEach(a => {
    active[a.id] = true;
    const prev = state[a.id];
    const repeatMs = (a.sev === 'CRITICAL' ? CRIT_REPEAT_H : WARN_REPEAT_H) * 3600000;
    if (!prev) {
        toSend.push(Object.assign({ kind: 'NEW' }, a));
        state[a.id] = { first: now, last: now, sev: a.sev, title: a.title };
    } else if (now - prev.last >= repeatMs) {
        const hrs = Math.round((now - prev.first) / 3600000);
        toSend.push(Object.assign({ kind: 'ONGOING', hours: hrs }, a));
        prev.last = now;
    }
});

Object.keys(state).forEach(id => {
    if (!active[id]) {
        const hrs = Math.round((now - state[id].first) / 3600000);
        toSend.push({ kind: 'RESOLVED', sev: state[id].sev, id,
                      title: state[id].title,
                      detail: `Cleared after about ${hrs} h.` });
        delete state[id];
    }
});

flow.set('alertState', state);

node.status({
    fill: alerts.some(a => a.sev === 'CRITICAL') ? 'red'
        : alerts.length ? 'yellow' : 'green',
    shape: 'dot',
    text: alerts.length ? `${alerts.length} active` : 'all clear'
});

if (!toSend.length) return null;

msg.alerts = toSend;
msg.summary = s;
return msg;

const a = msg.alerts || [];
const s = msg.summary || {};
const crit = a.filter(x => x.sev === 'CRITICAL' && x.kind !== 'RESOLVED');
const warn = a.filter(x => x.sev === 'WARNING' && x.kind !== 'RESOLVED');
const done = a.filter(x => x.kind === 'RESOLVED');

// Subject leads with the worst thing, so it is readable on a phone
// lock screen without opening the message.
let subject;
if (crit.length) subject = 'BMS CRITICAL: ' + crit[0].title + (crit.length > 1 ? ` (+${crit.length - 1} more)` : '');
else if (warn.length) subject = 'BMS warning: ' + warn[0].title + (warn.length > 1 ? ` (+${warn.length - 1} more)` : '');
else subject = 'BMS resolved: ' + done[0].title;

const L = [];
L.push('Apogee battery bank — ' + new Date().toLocaleString());
L.push('');

function block(title, items) {
    if (!items.length) return;
    L.push(title);
    L.push('-'.repeat(title.length));
    items.forEach(x => {
        L.push((x.kind === 'ONGOING' ? `[still active after ${x.hours} h] ` : '') + x.title);
        L.push('    ' + x.detail);
        L.push('');
    });
}

block('CRITICAL', crit);
block('WARNING', warn);
block('RESOLVED', done);

if (s.packs) {
    L.push('Current state');
    L.push('-------------');
    Object.keys(s.packs).sort().forEach(k => {
        const p = s.packs[k];
        const v = (p.voltage_v || {}).max;
        const soc = (p.soc_pct || {}).last;
        const d = (p.cell_delta_mv || {}).max;
        const t = (p.temp_c || {}).cell_max;
        // Surface FET state in the state block: a pack can be healthy on
        // every other number while sitting isolated from the bank.
        const fet = p.discharge_disabled_now ? '  [DISCHARGE OFF]'
                  : (p.charge_blocked_now ? '  [chg FET open]' : '');
        L.push(`${k}: ${v != null ? v.toFixed(3) + ' V' : '-'}  SoC ${soc != null ? soc + '%' : '-'}`
             + `  spread ${d != null ? d + ' mV' : '-'}  ${t != null ? t + ' C' : '-'}${fet}`);
    });
    L.push('');
    L.push(`Packs participating: ${s.packs_participating}/${s.packs_expected}`);
}

L.push('');
L.push('Dashboard: http://<gx-ip>:8088/');
L.push('Docs:      http://<gx-ip>:8088/docs');

// Return a clean message rather than mutating the one that came from the
// HTTP request node. Leftover properties - msg.headers and msg.statusCode
// in particular - make the e-mail node treat the body as a document and
// send it as an attachment instead of inline text.
return {
    topic: subject,
    payload: L.join('\n'),
};

// Forget what has already been notified, so the next poll re-sends any
// still-active condition. Useful after changing thresholds.
flow.set('alertState', {});
flow.set('missingSince', {});
flow.set('chargeBlockedSince', {});
node.status({ fill: 'blue', shape: 'dot', text: 'state cleared' });
return null;
